// src/types/pets.ts
// Data shape of public/data/pets/atlas.json (generated by scripts/import_pet_atlas.py).

export type PetCategory = "Cogni" | "Fera" | "Natura" | "Varian" | "Special";

export type PetSourceKind = "field" | "nonfield" | "special";

export interface PetZone {
  id: string;
  name: string;
  short: string;
  /** Map name, matches public/data/maps.yaml and UI/Map/WorldMap/<map>. */
  map: string;
  size: number;
}

export interface Pet {
  id: number;
  name: string;
  category: PetCategory;
  kind: PetSourceKind;
  /** Zone indexes this pet has field spawns in. */
  zones: number[];
  /** Spawn count per zone index. */
  spawnCounts: number[];
  /** Monster indexes per zone index. */
  sources: number[][];
}

export interface PetMonster {
  name: string;
  level: number;
  rank: string;
  zone: number;
}

/** [zoneIndex, petIndex, x, y, monsterIndex] — x/y in this app's map coordinates. */
export type PetSpawn = [number, number, number, number, number];

export interface PetAtlasData {
  meta: {
    schema: string;
    client: string;
    source: string;
    categories: PetCategory[];
    zones: PetZone[];
  };
  pets: Pet[];
  monsters: PetMonster[];
  spawns: PetSpawn[];
}

/** Pet id -> collected rank (0-3). */
export type PetRanks = Record<string, number>;

export const PET_MAX_RANK = 3;

export const PET_CATEGORY_COLORS: Record<PetCategory, string> = {
  Cogni: "#a993f0",
  Fera: "#54c79a",
  Natura: "#a3c94f",
  Varian: "#ec8d6f",
  Special: "#e0b866",
};
